      if (prior === "" || r[1] === "") return;
      const odds = prior/(1-prior);
      const expectInd = odds*lrInd/(1+odds*lrInd);
      const expectCons = odds*lrCons/(1+odds*lrCons);
      if (Math.abs((postInd||0)-expectInd) > tol) errs.push(`${name}!E${row} mismatch`);
      if (Math.abs((postCons||0)-expectCons) > tol) errs.push(`${name}!F${row} mismatch`);
    });
  });
  if (errs.length) throw new Error("QA mismatches:\n" + errs.join("\n"));
