import json, math
def check(file):
    data = json.load(open(file))
    errs = []
    def post(p, lr):
        o = p/(1-p)
        oo = o*lr
        return oo/(1+oo)
    for domain, block in data.items():
        if domain.startswith("_"): continue
        for i, r in enumerate(block["records"], 1):
            p = r["prior"]; li = r["lr_ind"]; lc = r["lr_cons"]
            pi = r.get("posterior_ind"); pc = r.get("posterior_cons")
            ei = post(p, li); ec = post(p, lc)
            if pi is not None and abs(pi - ei) > 1e-6:
                errs.append(f"{domain}[{i}] posterior_ind mismatch: got {pi:.6f}, expect {ei:.6f}")
            if pc is not None and abs(pc - ec) > 1e-6:
                errs.append(f"{domain}[{i}] posterior_cons mismatch: got {pc:.6f}, expect {ec:.6f}")
    if errs:
        print("Mismatches:"); print("\n".join(errs))
    else:
        print("All good.")
# usage: check("playbook.json")

Node.js
const fs = require("fs");
function post(p, lr){ const o=p/(1-p); const oo=o*lr; return oo/(1+oo); }
function check(path){
  const data = JSON.parse(fs.readFileSync(path, "utf8"));
  const errs = [];
  for (const domain of Object.keys(data)) {
    if (domain.startsWith("_")) continue;
    const recs = data[domain].records || data[domain]; // supports both grouped or flat
    recs.forEach((r, i) => {
      const ei = post(r.prior, r.lr_ind);
      const ec = post(r.prior, r.lr_cons);
      if ("posterior_ind" in r && Math.abs(r.posterior_ind - ei) > 1e-6)
        errs.push(`${domain}[${i+1}] posterior_ind mismatch`);
      if ("posterior_cons" in r && Math.abs(r.posterior_cons - ec) > 1e-6)
        errs.push(`${domain}[${i+1}] posterior_cons mismatch`);
    });
  }
  console.log(errs.length ? "Mismatches:\n" + errs.join("\n") : "All good.");
}
// usage: check("playbook.json")

